<script setup lang="ts">
import { computed, onMounted, onUnmounted, ref } from "vue";
import type {
  FlowStep,
  RecorderSession,
  RecorderStateResponse,
  RecordingHistoryEntry,
  RuntimeMessage
} from "../shared/schema";
import {
  appendRecordingHistory,
  clearRecordingHistory,
  formatHistoryTime,
  formatHistoryTitle,
  HISTORY_STORAGE_KEY,
  historyEntryToSession,
  loadRecordingHistory,
  removeRecordingHistoryEntry,
  sessionToHistoryEntry
} from "../shared/history";
import { exportSessionBundle } from "../shared/export-bundle";
import { createExportPayload, formatDuration } from "../shared/messages";

const session = ref<RecorderSession>();
const videoPreviewUrl = ref("");
const error = ref("");
const replayNotice = ref("");
const replayWarnings = ref<string[]>([]);
const isBusy = ref(false);
let replayNoticeTimer: number | undefined;
const captureSensitiveValues = ref(false);
const recordPostMessages = ref(false);
const recordingHistory = ref<RecordingHistoryEntry[]>([]);
const historyReplayId = ref("");
let pollTimer: number | undefined;
let storageListener: ((changes: Record<string, chrome.storage.StorageChange>) => void) | undefined;

const statusText = computed(() => {
  if (!session.value) {
    return "未开始";
  }

  const statusMap: Record<RecorderSession["status"], string> = {
    idle: "未开始",
    recording: "录制中",
    stopped: "已停止",
    error: "发生错误"
  };

  return statusMap[session.value.status];
});

const jsonPreview = computed(() => {
  if (!session.value) {
    return "{}";
  }

  return JSON.stringify(createExportPayload(session.value), null, 2);
});

const canExport = computed(() => Boolean(session.value?.steps.length));
const canDownloadVideo = computed(() => Boolean(session.value?.video && videoPreviewUrl.value));
const canPreviewVideo = computed(() => Boolean(session.value?.video && videoPreviewUrl.value));

const formatStepScope = (step: FlowStep): string => {
  const parts: string[] = [];

  if (step.tabId && step.tabId !== session.value?.tabId) {
    parts.push(`Tab ${step.tabId}`);
  }

  if (step.frameId && step.frameId !== 0) {
    parts.push("iframe");
  }

  return parts.join(" · ");
};

const sendMessage = async <T = RecorderStateResponse>(message: RuntimeMessage): Promise<T> => {
  const response = (await chrome.runtime.sendMessage(message)) as RecorderStateResponse;

  if (!response.ok) {
    throw new Error(response.error ?? "插件通信失败。");
  }

  return response as T;
};

const updateVideoPreview = (response: RecorderStateResponse): void => {
  if (!response.session?.video || !response.videoUrl) {
    videoPreviewUrl.value = "";
    return;
  }

  videoPreviewUrl.value = response.videoUrl;
};

const clearReplayNotice = (): void => {
  window.clearTimeout(replayNoticeTimer);
  replayNotice.value = "";
};

const showReplayNotice = (message: string): void => {
  replayNotice.value = message;
  window.clearTimeout(replayNoticeTimer);
  replayNoticeTimer = window.setTimeout(() => {
    replayNotice.value = "";
  }, 6000);
};

const applyState = (response: RecorderStateResponse): void => {
  session.value = response.session;
  error.value = response.error ?? response.session?.error ?? "";
  replayWarnings.value = response.replayWarnings ?? [];
  updateVideoPreview(response);
};

const refreshState = async (): Promise<void> => {
  try {
    applyState(await sendMessage({ type: "GET_STATE" }));
  } catch (refreshError: unknown) {
    error.value = refreshError instanceof Error ? refreshError.message : String(refreshError);
  }
};

const startPolling = (): void => {
  window.clearInterval(pollTimer);
  pollTimer = window.setInterval(() => {
    if (session.value?.status === "recording") {
      void refreshState();
    }
  }, 1000);
};

const startRecording = async (): Promise<void> => {
  isBusy.value = true;
  error.value = "";

  try {
    await chrome.storage.local.set({
      captureSensitiveValues: captureSensitiveValues.value,
      recordPostMessages: recordPostMessages.value
    });
    applyState(
      await sendMessage({
        type: "START_RECORDING",
        captureSensitiveValues: captureSensitiveValues.value,
        recordPostMessages: recordPostMessages.value
      })
    );
    startPolling();
  } catch (startError: unknown) {
    error.value = startError instanceof Error ? startError.message : String(startError);
  } finally {
    isBusy.value = false;
  }
};

const stopRecording = async (): Promise<void> => {
  isBusy.value = true;
  error.value = "";

  try {
    applyState(await sendMessage({ type: "STOP_RECORDING" }));
    await refreshHistory();
  } catch (stopError: unknown) {
    error.value = stopError instanceof Error ? stopError.message : String(stopError);
  } finally {
    isBusy.value = false;
  }
};

const replayFlow = async (): Promise<void> => {
  if (!session.value?.steps.length) {
    return;
  }

  const stepCount = session.value.steps.length;
  isBusy.value = true;
  error.value = "";
  clearReplayNotice();
  replayWarnings.value = [];

  try {
    const response = await sendMessage({ type: "REPLAY_FLOW", steps: session.value.steps });
    applyState(response);

    if (response.replayWarnings?.length) {
      const failedCount = response.replayWarnings.length;
      error.value = `部分步骤回放失败（${failedCount} 条），其余步骤已执行。`;
      showReplayNotice(`流程回放已结束：共 ${stepCount} 步，${failedCount} 步未成功。`);
    } else {
      showReplayNotice(`流程回放已完成，共执行 ${stepCount} 步。`);
    }
  } catch (replayError: unknown) {
    error.value = replayError instanceof Error ? replayError.message : String(replayError);
  } finally {
    isBusy.value = false;
  }
};

const exportJson = async (): Promise<void> => {
  if (!session.value) {
    return;
  }

  try {
    await exportSessionBundle(session.value);
  } catch (exportError: unknown) {
    error.value = exportError instanceof Error ? exportError.message : String(exportError);
  }
};

const refreshHistory = async (): Promise<void> => {
  recordingHistory.value = await loadRecordingHistory();
};

const keepCurrentSessionScreenshots = (): string[] => (session.value?.id ? [session.value.id] : []);

const deleteHistoryEntry = async (entry: RecordingHistoryEntry): Promise<void> => {
  const title = formatHistoryTitle(entry);
  if (!window.confirm(`确定删除「${title}」？此操作不可恢复。`)) {
    return;
  }

  try {
    await removeRecordingHistoryEntry(entry.id);
    await refreshHistory();
  } catch (deleteError: unknown) {
    error.value = deleteError instanceof Error ? deleteError.message : String(deleteError);
  }
};

const clearAllHistory = async (): Promise<void> => {
  if (!recordingHistory.value.length) {
    return;
  }

  if (!window.confirm(`确定清空全部 ${recordingHistory.value.length} 条录制历史？此操作不可恢复。`)) {
    return;
  }

  try {
    await clearRecordingHistory(keepCurrentSessionScreenshots());
    await refreshHistory();
  } catch (clearError: unknown) {
    error.value = clearError instanceof Error ? clearError.message : String(clearError);
  }
};

const ensureCurrentSessionInHistory = async (): Promise<void> => {
  if (session.value?.status !== "stopped" || !session.value.steps.length) {
    return;
  }

  const exists = recordingHistory.value.some((entry) => entry.id === session.value?.id);
  if (!exists) {
    await appendRecordingHistory(sessionToHistoryEntry(session.value));
  }
};

const exportHistoryJson = async (entry: RecordingHistoryEntry): Promise<void> => {
  try {
    await exportSessionBundle(historyEntryToSession(entry));
  } catch (exportError: unknown) {
    error.value = exportError instanceof Error ? exportError.message : String(exportError);
  }
};

const replayHistoryEntry = async (entry: RecordingHistoryEntry): Promise<void> => {
  if (!entry.steps.length) {
    return;
  }

  const stepCount = entry.steps.length;
  historyReplayId.value = entry.id;
  isBusy.value = true;
  error.value = "";
  clearReplayNotice();
  replayWarnings.value = [];

  try {
    const response = await sendMessage({
      type: "REPLAY_FLOW",
      steps: entry.steps,
      startUrl: entry.startUrl
    });
    applyState(response);

    if (response.replayWarnings?.length) {
      const failedCount = response.replayWarnings.length;
      error.value = `部分步骤回放失败（${failedCount} 条），其余步骤已执行。`;
      showReplayNotice(`「${formatHistoryTitle(entry)}」回放结束：共 ${stepCount} 步，${failedCount} 步未成功。`);
    } else {
      showReplayNotice(`「${formatHistoryTitle(entry)}」回放已完成，共执行 ${stepCount} 步。`);
    }
  } catch (replayError: unknown) {
    error.value = replayError instanceof Error ? replayError.message : String(replayError);
  } finally {
    historyReplayId.value = "";
    isBusy.value = false;
  }
};

const exportVideo = (): void => {
  if (!session.value?.video || !videoPreviewUrl.value) {
    return;
  }

  const anchor = document.createElement("a");
  anchor.href = videoPreviewUrl.value;
  anchor.download = session.value.video.fileName;
  anchor.click();
};

onMounted(() => {
  chrome.storage.local.get({ captureSensitiveValues: false, recordPostMessages: false }, (storedValues) => {
    captureSensitiveValues.value = Boolean(storedValues.captureSensitiveValues);
    recordPostMessages.value = Boolean(storedValues.recordPostMessages);
  });

  storageListener = (changes) => {
    if (changes[HISTORY_STORAGE_KEY]) {
      void refreshHistory();
    }
  };
  chrome.storage.onChanged.addListener(storageListener);

  void (async () => {
    await refreshState();
    await refreshHistory();
    await ensureCurrentSessionInHistory();
    await refreshHistory();
  })();
  startPolling();
});

onUnmounted(() => {
  window.clearInterval(pollTimer);
  clearReplayNotice();
  if (storageListener) {
    chrome.storage.onChanged.removeListener(storageListener);
  }
});
</script>

<template>
  <main class="app-shell">
    <header class="header">
      <div>
        <h1>元素探测与流程录制</h1>
      </div>
      <span class="status" :class="session?.status">{{ statusText }}</span>
    </header>

    <section class="panel controls">
      <button class="primary" :disabled="isBusy || session?.status === 'recording'" @click="startRecording">
        开始录制
      </button>
      <button :disabled="isBusy || session?.status !== 'recording'" @click="stopRecording">停止录制</button>
      <button :disabled="isBusy || !canExport" @click="replayFlow">流程回放</button>
    </section>

    <label class="sensitive-option">
      <input v-model="captureSensitiveValues" type="checkbox" :disabled="session?.status === 'recording'" />
      <span>
        记录真实密码用于回放
        <small>默认关闭；开启后 JSON 会包含明文密码，请只在受信环境使用。</small>
      </span>
    </label>

    <label class="sensitive-option">
      <input v-model="recordPostMessages" type="checkbox" :disabled="session?.status === 'recording'" />
      <span>
        录制 postMessage（SPA / 子应用通信）
        <small>可选；用于通过 postMessage 驱动路由或弹层的页面。</small>
      </span>
    </label>

    <p v-if="replayNotice" class="success" role="status">{{ replayNotice }}</p>
    <p v-if="error" class="error">{{ error }}</p>
    <ul v-if="replayWarnings.length" class="warning-list">
      <li v-for="warning in replayWarnings" :key="warning">{{ warning }}</li>
    </ul>

    <section class="stats">
      <article>
        <span>时长</span>
        <strong>{{ formatDuration(session?.durationMs ?? 0) }}</strong>
      </article>
      <article>
        <span>步骤</span>
        <strong>{{ session?.steps.length ?? 0 }}</strong>
      </article>
      <article>
        <span>视频</span>
        <strong>{{ session?.video ? '已生成' : '待生成' }}</strong>
      </article>
    </section>

    <section class="panel">
      <div class="section-title">
        <h2>视频回放预览</h2>
        <button :disabled="!canDownloadVideo" @click="exportVideo">导出 WebM</button>
      </div>

      <video v-if="canPreviewVideo" class="video-preview" :src="videoPreviewUrl" controls playsinline />
      <p v-else class="empty">停止录制后，这里会显示录制视频，可直接播放预览。</p>
    </section>

    <section class="panel">
      <div class="section-title">
        <h2>流程步骤</h2>
        <div class="actions">
          <button :disabled="!canExport" @click="exportJson">导出 ZIP</button>
        </div>
      </div>

      <ol v-if="session?.steps.length" class="steps">
        <li v-for="step in session.steps" :key="step.id">
          <span class="step-type">{{ step.type }}</span>
          <span class="step-target">
            <em v-if="formatStepScope(step)" class="step-scope">{{ formatStepScope(step) }}</em>
            {{ step.target?.text || step.target?.selector || step.scroll?.y || step.key }}
          </span>
          <small>{{ step.timestampMs }}ms</small>
        </li>
      </ol>
      <p v-else class="empty">点击“开始录制”后，正常操作网页即可自动生成步骤。</p>
    </section>

    <section class="panel">
      <div class="section-title">
        <h2>JSON 预览</h2>
      </div>
      <pre class="json-preview">{{ jsonPreview }}</pre>
    </section>

    <section class="panel">
      <div class="section-title">
        <h2>录制历史</h2>
        <div class="history-header-actions">
          <span class="history-count">{{ recordingHistory.length }} 条</span>
          <button
            class="danger"
            type="button"
            :disabled="!recordingHistory.length || isBusy"
            @click="clearAllHistory"
          >
            清空历史
          </button>
        </div>
      </div>

      <ul v-if="recordingHistory.length" class="history-list">
        <li v-for="entry in recordingHistory" :key="entry.id" class="history-item">
          <div class="history-main">
            <strong class="history-title">{{ formatHistoryTitle(entry) }}</strong>
            <p class="history-meta">
              {{ formatHistoryTime(entry.startedAt) }}
              · {{ formatDuration(entry.durationMs) }}
              · {{ entry.steps.length }} 步
            </p>
            <p class="history-url">{{ entry.startUrl }}</p>
          </div>
          <div class="history-actions">
            <button
              :disabled="isBusy || !entry.steps.length"
              @click="replayHistoryEntry(entry)"
            >
              {{ historyReplayId === entry.id ? "回放中…" : "回放" }}
            </button>
            <button :disabled="!entry.steps.length" @click="exportHistoryJson(entry)">导出 ZIP</button>
            <button
              class="danger"
              type="button"
              :disabled="isBusy"
              @click="deleteHistoryEntry(entry)"
            >
              删除
            </button>
          </div>
        </li>
      </ul>
      <p v-else class="empty">完成录制后，历史记录会显示在这里，可对每条记录单独回放或导出 ZIP（含 flow.json 与截图）。</p>
    </section>
  </main>
</template>
