import JSZip from "jszip";
import type { RecorderSession } from "./schema";
import { createExportPayload, downloadBlob } from "./messages";
import { getSessionHtml, getSessionScreenshots } from "./screenshot-db";
import { getHtmlFileName } from "./html-path";
import { dataUrlToBase64, getScreenshotFileName } from "./screenshot-path";

export const exportSessionBundle = async (session: RecorderSession): Promise<void> => {
  const screenshots = await getSessionScreenshots(session.id);
  const htmlByStep = await getSessionHtml(session.id);
  const zip = new JSZip();
  const payload = createExportPayload(session);

  zip.file("flow.json", JSON.stringify(payload, null, 2));

  const screenshotFolder = zip.folder("screenshots");
  const htmlFolder = zip.folder("html");
  for (const step of session.steps) {
    if (step.screenshot) {
      const dataUrl = screenshots[step.id];
      if (dataUrl) {
        screenshotFolder?.file(getScreenshotFileName(step.id), dataUrlToBase64(dataUrl), { base64: true });
      }
    }

    if (step.html) {
      const html = htmlByStep[step.id];
      if (html) {
        htmlFolder?.file(getHtmlFileName(step.id), html);
      }
    }
  }

  const blob = await zip.generateAsync({ type: "blob" });
  downloadBlob(blob, `${session.id}.zip`);
};
